struct Params { time: f32 }
@group(0) @binding(0) var<uniform> params: Params;

fn hash21(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453123);
}

fn hash22(p: vec2f) -> vec2f {
  let n = vec2f(dot(p, vec2f(127.1, 311.7)), dot(p, vec2f(269.5, 183.3)));
  return fract(sin(n) * 43758.5453);
}

fn noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = hash21(i);
  let b = hash21(i + vec2f(1.0, 0.0));
  let c = hash21(i + vec2f(0.0, 1.0));
  let d = hash21(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn fbm(p: vec2f) -> f32 {
  var v = 0.0;
  var a = 0.5;
  var q = p;
  for (var k = 0; k < 5; k = k + 1) {
    v = v + a * noise(q);
    q = q * 2.07 + vec2f(11.3, 5.7);
    a = a * 0.5;
  }
  return v;
}

fn voronoi_edge(p: vec2f) -> f32 {
  let n = floor(p);
  let f = fract(p);
  var md = 8.0;
  var mr = vec2f(0.0);
  var mg = vec2f(0.0);
  for (var j = -1; j <= 1; j = j + 1) {
    for (var i = -1; i <= 1; i = i + 1) {
      let g = vec2f(f32(i), f32(j));
      let o = hash22(n + g);
      let r = g + o - f;
      let d = dot(r, r);
      if (d < md) {
        md = d;
        mr = r;
        mg = g;
      }
    }
  }
  var ed = 8.0;
  for (var j = -2; j <= 2; j = j + 1) {
    for (var i = -2; i <= 2; i = i + 1) {
      let g = mg + vec2f(f32(i), f32(j));
      let o = hash22(n + g);
      let r = g + o - f;
      let diff = r - mr;
      let len2 = dot(diff, diff);
      if (len2 > 1.0e-6) {
        ed = min(ed, dot(0.5 * (mr + r), diff * inverseSqrt(len2)));
      }
    }
  }
  return ed;
}

fn magma_col(h: f32) -> vec3f {
  let x = clamp(h, 0.0, 1.0);
  let c0 = vec3f(0.05, 0.008, 0.002);
  let c1 = vec3f(0.42, 0.035, 0.008);
  let c2 = vec3f(0.92, 0.18, 0.015);
  let c3 = vec3f(1.0, 0.52, 0.08);
  let c4 = vec3f(1.0, 0.88, 0.42);
  if (x < 0.22) { return mix(c0, c1, x / 0.22); }
  if (x < 0.50) { return mix(c1, c2, (x - 0.22) / 0.28); }
  if (x < 0.78) { return mix(c2, c3, (x - 0.50) / 0.28); }
  return mix(c3, c4, (x - 0.78) / 0.22);
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.time;
  let p = vec2f(uv.x * 0.5625, uv.y);

  let warp = vec2f(fbm(p * 2.4 + vec2f(2.1, 0.4)) - 0.5, fbm(p * 2.4 + vec2f(8.7, 3.2)) - 0.5);
  let pw = p + warp * 0.085;

  let v1 = voronoi_edge(pw * 5.4 + vec2f(0.6, 1.2));
  let v2 = voronoi_edge(pw * 11.0 + vec2f(4.8, 0.3));
  let plates = min(v1, v2 * 0.72 + 0.02);

  let meander = 0.28 + 0.10 * sin(p.y * 7.2 + 0.85) + 0.035 * sin(p.y * 18.0 + 1.4);
  let rift = abs(p.x - meander) - 0.012 * (0.6 + fbm(vec2f(p.y * 6.0, 2.0)));
  let trib = abs(p.x - (0.12 + 0.06 * sin(p.y * 9.5 + 2.2))) - 0.004;
  let trib2 = abs(p.x - (0.44 + 0.05 * sin(p.y * 11.0))) - 0.0035;
  let channel = min(rift, min(trib, trib2) + 0.008);

  let crackW = 0.028 + 0.012 * fbm(p * 8.0);
  let seams = 1.0 - smoothstep(0.0, crackW, plates);
  let riftFill = 1.0 - smoothstep(-0.006, 0.034, channel);
  let cracks = max(seams * 0.85, riftFill);

  let flow = fbm(vec2f(p.x * 9.0, p.y * 4.2 - t * 0.18) + warp * 1.6);
  let pulse = 0.82 + 0.18 * sin(t * 0.7 + p.y * 5.0 + flow * 4.0);
  var heat = cracks * (0.55 + 0.45 * flow) * pulse;
  heat = heat + riftFill * (0.35 + 0.40 * flow);
  heat = clamp(heat, 0.0, 1.0);

  let bloom = exp(-max(plates, 0.0) * 14.0) * 0.55
            + exp(-max(channel, 0.0) * 9.0) * 0.85
            + exp(-max(plates, 0.0) * 4.5) * 0.22;
  heat = clamp(heat + bloom * 0.38, 0.0, 1.35);

  let crustN = fbm(p * 22.0 + vec2f(3.0, 1.0));
  let grit = fbm(p * 54.0);
  var basalt = vec3f(0.016, 0.013, 0.011)
             + crustN * vec3f(0.028, 0.022, 0.018)
             + grit * vec3f(0.012, 0.010, 0.008);
  let raised = smoothstep(0.03, 0.09, plates) * (1.0 - smoothstep(0.09, 0.20, plates));
  basalt = basalt + vec3f(0.045, 0.032, 0.022) * raised * (0.4 + crustN);
  let ash = fbm(p * 7.0 + vec2f(9.0, 2.0));
  basalt = mix(basalt, vec3f(0.035, 0.028, 0.024), ash * 0.22 * (1.0 - cracks));

  let lava = magma_col(heat);
  let core = pow(clamp(heat, 0.0, 1.0), 3.2);
  var col = mix(basalt, lava, clamp(heat * 1.15, 0.0, 1.0));
  col = col + vec3f(1.0, 0.55, 0.12) * bloom * 0.22;
  col = col + vec3f(1.0, 0.82, 0.28) * core * 0.55;
  col = col + vec3f(0.55, 0.10, 0.02) * pow(clamp(bloom, 0.0, 1.0), 1.6) * 0.18;

  let vig = smoothstep(1.15, 0.22, length((uv - vec2f(0.5, 0.52)) * vec2f(1.15, 1.0)));
  col = col * (0.55 + 0.45 * vig);
  col = col * vec3f(1.04, 0.98, 0.90);

  return vec4f(clamp(col, vec3f(0.0), vec3f(1.0)), 1.0);
}
